<?php
declare(strict_types=1);define('_GNUBOARD_',true);require __DIR__.'/../../deploy/noa-app/database/core.php';
function ok(bool $v,string $m): void {if(!$v)throw new RuntimeException($m);}
$compile=fn($s)=>(new NoaSelect($s))->compile(['songs','members'],fn($t)=>['id','title','n','secret']);
foreach(["SELECT * FROM songs", "SELECT id, title FROM songs WHERE title LIKE '%가을%' AND (id >= 2 OR n IS NULL) ORDER BY id DESC LIMIT 5000", "SELECT COUNT(*) AS total FROM songs", "SELECT title, SUM(n) FROM songs GROUP BY title ORDER BY title LIMIT 10 OFFSET 20", "SELECT title FROM songs WHERE title = 'it''s; DROP TABLE songs'", "SELECT DISTINCT title FROM songs WHERE title <> 'secret'"] as $s){$p=$compile($s);ok(str_starts_with($p['sql'],'SELECT '),'select');ok($p['limit']<=1000,'limit');}
$p=$compile("SELECT title FROM songs WHERE title='hi' LIMIT 9999");ok($p['params']===['hi'],'bind literals');ok(str_ends_with($p['sql'],'LIMIT 1000 OFFSET 0'),'hard row cap');
$bad=['DELETE FROM songs','UPDATE songs SET n=0','DROP TABLE songs','TRUNCATE songs','ALTER TABLE songs ADD x INT','INSERT INTO songs VALUES(1)', 'SELECT * FROM songs; DELETE FROM songs', 'SELECT /* hello */ * FROM songs', 'SELECT /*!50000 SQL_NO_CACHE */ * FROM songs','SELECT * FROM songs -- test','SELECT * FROM songs # test','SELECT * INTO OUTFILE \'/tmp/x\' FROM songs','SELECT * FROM songs INTO DUMPFILE \'/tmp/x\'','SELECT SLEEP(10) FROM songs','SELECT BENCHMARK(10,n) FROM songs','SELECT LOAD_FILE(\'/tmp/x\') FROM songs','SELECT GET_LOCK(\'x\',10) FROM songs','SELECT evil() FROM songs','SELECT * FROM mysql.user','SELECT * FROM songs FOR UPDATE','SELECT * FROM songs LOCK IN SHARE MODE','SELECT @x:=1 FROM songs','SELECT * FROM songs UNION SELECT * FROM members','SELECT * FROM songs JOIN members ON 1=1','SELECT * FROM (SELECT * FROM songs) x','WITH x AS (SELECT * FROM songs) SELECT * FROM x','SELECT * FROM songs WHERE n=1;','SELECT * FROM unknown','SELECT no_column FROM songs','SELECT * FROM songs LIMIT -1',"SELECT * FROM songs WHERE title='x\\' OR n=1",'SELECT secret FROM songs PROCEDURE ANALYSE()'];
foreach($bad as $s){try{$compile($s);throw new RuntimeException('UNSAFE ACCEPTED: '.$s);}catch(InvalidArgumentException $expected){}}
echo 'SELECT grammar: '.(count($bad)+8)." valid/malicious cases passed\n";
